import pandas as pd
import json
import os
import shutil

def task_func(path):
    os.makedirs(path, exist_ok=True)
    processed_dir = os.path.join(path, "processed")
    os.makedirs(processed_dir, exist_ok=True)

    frames = []

    json_files = sorted(
        filename
        for filename in os.listdir(path)
        if filename.lower().endswith(".json") and os.path.isfile(os.path.join(path, filename))
    )

    for filename in json_files:
        file_path = os.path.join(path, filename)
        dest_path = os.path.join(processed_dir, filename)

        try:
            with open(file_path, "r", encoding="utf-8") as f:
                data = json.load(f)

            if isinstance(data, list):
                df_file = pd.DataFrame(data)
            elif isinstance(data, dict):
                df_file = pd.DataFrame([data])
            else:
                df_file = pd.DataFrame([{"value": data}])

            df_file["Source"] = filename

            if os.path.exists(dest_path):
                if os.path.isdir(dest_path):
                    shutil.rmtree(dest_path)
                else:
                    os.remove(dest_path)
            shutil.move(file_path, dest_path)

            frames.append(df_file)
        except (json.JSONDecodeError, ValueError, OSError, TypeError):
            continue

    if frames:
        df = pd.concat(frames, ignore_index=True)
    else:
        df = pd.DataFrame()

    return df
